def solve(H_km=8.0, radius_km=8.0, z0=0.0, z1=1.0, z2=2.0, z3=3.0):
    import math
    # Let x = z/H. Density is rho = rho0 exp(-x).
    # For a spherical atmosphere, mass in a shell is proportional to
    # exp(-x) * (R + z)^2 dz = exp(-x) * (R/H + x)^2 dx.
    r = radius_km / H_km

    def P(x):
        # Integral helper: integral exp(-x)*(x+r)^2 dx = -exp(-x)*P(x)
        return x*x + 2.0*(r + 1.0)*x + r*r + 2.0*r + 2.0

    def shell_fraction(a, b):
        numerator = math.exp(-a) * P(a) - math.exp(-b) * P(b)
        denominator = r*r + 2.0*r + 2.0
        return numerator / denominator

    return {
        "1": {"value": shell_fraction(z0, z1), "unit": "dimensionless"},
        "2": {"value": shell_fraction(z1, z2), "unit": "dimensionless"},
        "3": {"value": shell_fraction(z2, z3), "unit": "dimensionless"}
    }

